package maintenance

const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Workspace updates</title><link rel="icon" href="/branding/icons/one_workspace.svg"><style>
body{margin:0;background:#f5f7fc;color:#18233b;font:16px system-ui,sans-serif}main{max-width:960px;margin:48px auto;padding:24px}header{display:flex;align-items:center;gap:16px}header img{width:64px;height:64px}h1{letter-spacing:-1px;margin-bottom:6px}p{line-height:1.6;color:#5e6c84}.card{background:white;border:1px solid #e3e8f4;border-radius:20px;padding:24px;margin:24px 0}button,.button{background:#345de5;color:white;border:0;padding:12px 18px;border-radius:10px;font:inherit;cursor:pointer;text-decoration:none}button:disabled{opacity:.5;cursor:wait}.secondary{background:#eaf0ff;color:#2649b2}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}table{width:100%;border-collapse:collapse;text-align:left}td,th{padding:16px 8px;border-bottom:1px solid #e3e8f4}small{display:block;color:#69758d;margin-top:5px;max-width:530px}input[type=text],select{box-sizing:border-box;padding:12px;border:1px solid #c8d2e6;border-radius:10px;max-width:100%;width:100%;font:inherit}input[type=checkbox]{width:20px;height:20px}#error{color:#ae273d;white-space:pre-wrap;overflow-wrap:anywhere}#phase{font-weight:600}a{color:#345de5}.muted{color:#69758d}#pending{background:#fff4d8;padding:18px;border-radius:12px}footer{font-size:13px;color:#69758d;margin-top:28px}@media(max-width:600px){main{margin:12px auto;padding:16px}.card{padding:16px}td,th{padding:10px 4px}th:nth-child(3),td:nth-child(3){display:none}}
 .progress-head{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.progress-head h2{margin:0;font-size:21px}progress{display:block;width:100%;height:14px;accent-color:#345de5;margin:16px 0}#current-detail{font-weight:600;color:#18233b}#transfer,#timing,#heartbeat{font-variant-numeric:tabular-nums}#heartbeat{color:#895a09}#steps{list-style:none;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:8px 20px}#steps li{padding:10px 12px;border-radius:10px;background:#f5f7fc;color:#69758d}#steps li[data-state=running]{background:#eaf0ff;color:#2649b2;font-weight:600}#steps li[data-state=done]{color:#197448}#steps li[data-state=failed]{background:#fff0f0;color:#ae273d}#steps li[data-state=skipped]{opacity:.65}#activity{padding-left:20px;color:#69758d;font-size:14px}#activity li{margin:8px 0;overflow-wrap:anywhere}.complete{color:#197448}.failed{color:#ae273d}@media(max-width:600px){#steps{grid-template-columns:1fr}}
[hidden]{display:none!important}
</style></head><body><main><header><img src="/branding/icons/one_workspace.svg" alt="One Workspace"><div><h1>Workspace updates</h1><p id="installed">Your apps, kept up to date.</p></div></header>
<section class="card"><p id="phase" role="status" aria-live="polite">Opening your installation…</p><p id="error" role="alert"></p><div id="pending" hidden><b>An interrupted update needs recovery.</b><p>Recover the verified backup before starting another update.</p><button id="recover">Recover installation</button></div><div class="actions"><button id="check">Check for updates</button><a id="open" class="button secondary" hidden>Open Workspace</a></div></section>
<section class="card"><h2>Available releases</h2><p>Apps that share a backend update together. New default apps are installed with Workspace updates. Apps unchecked during setup stay excluded. Your locations, accounts and settings stay in place.</p><div style="overflow-x:auto"><table><thead><tr><th>Install</th><th>App</th><th>Installed</th><th>Available</th></tr></thead><tbody id="choices"><tr><td colspan="4">Check for updates to see available releases.</td></tr></tbody></table></div><p>Close other editors before updating. Workspace and its apps briefly stop while a verified backup is created. Startup is checked before access reopens; a failed update restores the previous state.</p><label for="backup">Backup location (optional)</label><input id="backup" type="text" placeholder="Leave blank to use Private\backups"><small>Choose another local NTFS folder for large libraries. Two full copies of programs, private data and ordinary files plus working space must fit. After successful startup, the latest verified update rollback is kept and older automatic update copies are removed. Scheduled backups and recovery archives stay intact.</small><div class="actions"><button id="apply" disabled>Back up and install selected updates</button></div></section>
<section class="card" id="cleanup-card" hidden><h2>Update cleanup</h2><p id="cleanup-summary" role="status"></p><p id="cleanup-warning" role="status"></p><small>Scheduled backups, recovery archives, unknown legacy copies and unregistered app runtime caches are preserved.</small></section>
<section class="card"><h2>Restore a workspace backup</h2><p>Restoring archives the current installation first, including changes made since the selected snapshot. The selected backup is then restored. Newer files remain recoverable in that archive.</p><label for="backups">Verified workspace backups</label><select id="backups"><option value="">No recorded backups</option></select><div class="actions"><button id="rollback" class="secondary" disabled>Archive current state and restore backup</button><button id="close" class="secondary">Close updater</button></div></section><footer>Windows-local maintenance window · Downloads are limited to verified organization releases. Releases without a managed compatibility contract are listed for review.</footer></main><script>
const token=location.hash.slice(1)||sessionStorage.getItem('workspace-update-token');if(location.hash){sessionStorage.setItem('workspace-update-token',token);history.replaceState(null,'',location.pathname)}
const $=id=>document.getElementById(id);let lastPlan='',lastBackups='',busy=false,pending=false,refreshing=false;
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'X-Workspace-Update':token||'','Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(await r.text());return r.status===202?null:await r.json()}
function selected(){return [...document.querySelectorAll('#choices input:checked')].map(e=>e.value)}
function buttons(){const workspace=document.querySelector('#choices input[value=workspace]');if(workspace?.checked){for(const e of document.querySelectorAll('#choices input[data-new-app=true]'))e.checked=true}for(const id of ['check','recover','rollback','close','backup','backups'])$(id).disabled=busy;const has=document.querySelector('#choices input');$('apply').disabled=busy||pending||!has||!selected().length;$('apply').textContent=busy?'Working… see progress above':'Back up and install selected updates';$('check').disabled=busy||pending;$('rollback').disabled=busy||pending||!$('backups').value;for(const e of document.querySelectorAll('#choices input'))e.disabled=busy||pending||(workspace?.checked&&e.dataset.newApp==='true')}
async function refresh(){if(refreshing)return;refreshing=true;try{const s=await api('state');updateProgress(s.progress);busy=s.busy;pending=s.pending;$('phase').textContent=s.phase;$('error').textContent=s.error;$('installed').textContent='Installed Workspace '+s.version;$('cleanup-card').hidden=!s.cleanup;if(s.cleanup){$('cleanup-summary').textContent='Removed '+s.cleanup.removedBackups+' older update backup(s) and '+s.cleanup.removedStages+' temporary folder(s), freeing approximately '+(s.cleanup.bytesFreed/1e6).toFixed(1)+' MB. Latest recovery copy retained.';$('cleanup-warning').textContent=(s.cleanup.warnings||[]).join(' ');}$('pending').hidden=!pending;$('open').href=s.origin;$('open').hidden=busy||pending;
const p=JSON.stringify(s.plan);if(p!==lastPlan&&!s.plan){lastPlan=p;$('choices').replaceChildren();const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=4;td.textContent='Check for updates to see available releases.';tr.append(td);$('choices').append(tr)}if(p!==lastPlan&&s.plan){lastPlan=p;$('choices').replaceChildren();for(const c of s.plan.choices){const tr=document.createElement('tr'),cell=document.createElement('td'),box=document.createElement('input');box.type='checkbox';box.value=c.id;if(c.newApps?.length)box.dataset.newApp='true';box.checked=c.available;box.hidden=!c.available;box.setAttribute('aria-label','Update '+c.name);box.onchange=buttons;cell.append(box);tr.append(cell);const name=document.createElement('td'),link=document.createElement('a');link.textContent=c.name;link.href=c.source;link.target='_blank';link.rel='noreferrer';name.append(link);if(c.newApps?.length){const hint=document.createElement('small');hint.textContent='New app: included when updating Workspace.';name.append(hint)}if(c.reason){const small=document.createElement('small');small.textContent=c.reason;name.append(small)}if(c.reviewUrl){const review=document.createElement('a');review.href=c.reviewUrl;review.target='_blank';review.rel='noreferrer';review.textContent='Review newer standalone release';const small=document.createElement('small');small.append(review);name.append(small)}tr.append(name);for(const value of [c.current,c.available?c.version:c.reason?'Review release':'Up to date']){const td=document.createElement('td');td.textContent=value;tr.append(td)}$('choices').append(tr)}}
const b=JSON.stringify(s.backups);if(b!==lastBackups){lastBackups=b;$('backups').replaceChildren();const empty=document.createElement('option');empty.value='';empty.textContent='Choose a recorded backup';$('backups').append(empty);for(const r of s.backups||[]){const opt=document.createElement('option');opt.value=r.id;opt.disabled=!!r.recoveryOnly||!!r.cleanupPending;opt.textContent=r.version+' · '+new Date(r.created).toLocaleString()+(r.cleanupPending?' · Removal needs attention':r.recoveryOnly?' · Recovery archive':'');$('backups').append(opt)}}buttons()}catch(e){disconnected=true;$('error').textContent='Could not read update status. Reconnecting… '+e.message;renderProgress()}finally{refreshing=false}}
async function action(path,body={}){busy=true;buttons();try{await api(path,body);await refresh()}catch(e){$('error').textContent=e.message;busy=false;buttons()}}
` + progressScript + `
$('check').onclick=()=>action('check');$('apply').onclick=()=>action('apply',{selected:selected(),backupRoot:$('backup').value.trim()});$('recover').onclick=()=>action('recover');$('rollback').onclick=()=>action('rollback',{id:$('backups').value});$('backups').onchange=buttons;$('close').onclick=async()=>{try{await api('close',{});$('phase').textContent='Updater closed. You can close this window.';clearInterval(timer)}catch(e){$('error').textContent=e.message}};refresh();const timer=setInterval(refresh,1500);
</script></body></html>`
